// Minimal typings for the vendored ssh2 bundle (`vendor/ssh2.bundle.cjs`).
//
// The bundle is generated by `scripts/build-vendor.mjs` and ships no declarations; `vendor/`
// is generated output, so the declaration has to live outside it. Only the surface
// `src/ssh.ts` actually drives is declared here — the Client class, its four methods, the two
// event names it subscribes to, and the channel/SFTP shapes it reads. Nothing is `any`.
//
// The module name is a path pattern rather than `declare module '*'`: an ambient declaration
// for a *relative* specifier is not matched by TypeScript (the specifier in `src/ssh.ts` is
// `../vendor/ssh2.bundle.cjs`, whose target path is not in the program), so the narrowest
// declaration that does apply is the one that matches that one vendored path.
declare module '*/vendor/ssh2.bundle.cjs' {
  import type { EventEmitter } from 'node:events'
  import type { Duplex, Readable } from 'node:stream'

  /** The `Attributes` an SFTP `stat`/`readdir` call reports; every getter is optional to call. */
  export interface SftpStats {
    size?: number
    mtime?: number
    isFile?: () => boolean
    isDirectory?: () => boolean
    isSymbolicLink?: () => boolean
  }

  /** One `readdir` entry: the file name plus its attributes. */
  export interface SftpDirEntry {
    filename?: string
    attrs?: SftpStats
  }

  /** The SFTP session surface `src/ssh.ts` drives: stat, list, one read stream, end. */
  export interface SftpSession {
    stat(path: string, callback: (error: Error | undefined, stats: SftpStats) => void): void
    readdir(path: string, callback: (error: Error | undefined, listing: SftpDirEntry[]) => void): void
    createReadStream(path: string): Readable
    end(): void
  }

  /**
   * One forwarded/exec channel: a duplex stream for the pipe, plus the ssh2-specific `stderr`
   * sibling and a `close` event that carries the exit code and signal.
   */
  export interface ClientChannel extends Duplex {
    readonly stderr: Readable
  }

  /** Host-key verification callback: answer exactly once, asynchronously or synchronously. */
  export type HostVerifier = (keyBlob: Buffer, verify: (accepted: boolean) => void) => void

  /** The connect fields this plugin sets; auth is a spread of one auth candidate. */
  export interface ConnectConfig {
    host: string
    port: number
    username?: string
    readyTimeout?: number
    keepaliveInterval?: number
    keepaliveCountMax?: number
    tryKeyboard?: boolean
    sock?: Duplex
    password?: string
    privateKey?: Buffer
    hostVerifier?: HostVerifier
  }

  /** Per-command options: only the environment is used. */
  export interface ExecOptions {
    env?: Record<string, string>
  }

  /** The ssh2 client: an EventEmitter that also owns the transport methods below. */
  export class Client extends EventEmitter {
    connect(config: ConnectConfig): void
    end(): void
    exec(
      command: string,
      options: ExecOptions,
      callback: (error: Error | undefined, channel: ClientChannel) => void,
    ): void
    sftp(callback: (error: Error | undefined, sftp: SftpSession) => void): void
    forwardOut(
      srcHost: string,
      srcPort: number,
      destHost: string,
      destPort: number,
      callback: (error: Error | undefined, channel: ClientChannel) => void,
    ): void
  }

  /** The bundle's CommonJS export shape: `const { Client } = require(...)`. */
  const ssh2: { Client: typeof Client }

  export default ssh2
}
